-- GenDB engine variant Q17-wrapped_tables: template q17.sql, kind wrapped_tables (generated by generate.py; frozen)
SELECT
  SUM(l_extendedprice) / 7.0 AS avg_yearly
FROM (
  SELECT
    *
  FROM lineitem
) AS lineitem, (
  SELECT
    *
  FROM part
) AS part
WHERE
  p_partkey = l_partkey
  AND p_brand = $1
  AND p_container = $2
  AND l_quantity < (
    SELECT
      0.2 * AVG(l_quantity)
    FROM (
      SELECT
        *
      FROM lineitem
    ) AS lineitem
    WHERE
      l_partkey = p_partkey
  )
